script:
cargo = env.run(["cargo", "--version"], check=False)
rustc = env.run(["rustc", "--version"], check=False)
return {"cargo": cargo.code, "cargo_out": cargo.stdout.strip(), "cargo_err": cargo.stderr.strip()[:300],
        "rustc": rustc.code, "rustc_out": rustc.stdout.strip(), "rustc_err": rustc.stderr.strip()[:300]}

a = repo.read("Cargo.toml")
r = env.run(["cargo", "test", "--no-fail-fast"], check = False)
return {"toml": a, "code": r.code, "stdout": r.stdout, "stderr": r.stderr}

res = env.run(["awk", "{print $1}", "logs/large.log"])
levels = {}
for line in res.stdout.splitlines():
    if line == "":
        continue
    levels[line] = levels.get(line, 0) + 1
# also check for case-insensitive 'error' anywhere, and 'ERR'
res2 = env.run(["grep", "-in", "error", "logs/large.log"], check=False)
res3 = env.run(["grep", "-in", "err", "logs/large.log"], check=False)
return {"levels": levels, "case_insens_error": res2.stdout.splitlines(), "err_substr": res3.stdout.splitlines()}

files = repo.list(".")
result = env.run(["cargo", "--version"], check=False)
return {"files": files, "cargo": result.stdout}

r = env.run(["cargo", "--version"], check=False)
r2 = env.run(["rustc", "--version"], check=False)
return {"cargo": {"code": r.code, "stdout": r.stdout, "stderr": r.stderr}, "rustc": {"code": r2.code, "stdout": r2.stdout, "stderr": r2.stderr}}

result = env.run(["cargo", "test", "--workspace", "--no-fail-fast"], check = False)
return {
    "code": result.code,
    "stdout": result.stdout,
    "stderr": result.stderr,
}

res = env.run(["cargo", "test", "--lib", "--", "--nocapture"], check = False)
out = res.stdout
return {"code": res.code, "stdout": out, "stderr": res.stderr[-4000:]}

result({
  "git_log": env.run(["git", "log", "--oneline", "-5"], check=False).stdout,
  "git_files": env.run(["git", "ls-files"], check=False).stdout,
  "cargo_version": env.run(["cargo", "--version"], check=False).stdout,
  "hidden": repo.list("."),
})

result({
  "compat": [h.path + ":" + str(h.line) + ": " + h.text for h in repo.search("compatibility|legacy frame", glob = "**/*")],
  "all_files": env.run(["bash", "-lc", "ls -la; find . -path ./target -prune -o -type f -print"], check = False).stdout,
})

result({
  "which_cargo": env.run(["which", "cargo"], check=False).stdout,
  "which_rustc": env.run(["which", "rustc"], check=False).stdout,
  "path": env.run(["printenv", "PATH"], check=False).stdout,
  "home": env.run(["printenv", "HOME"], check=False).stdout,
})
